CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),username text UNIQUE NOT NULL,full_name text NOT NULL,role text NOT NULL CHECK(role IN('owner','pharmacist','cashier','manager')),pin_hash text NOT NULL,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sku text UNIQUE NOT NULL,barcode text UNIQUE,name text NOT NULL,generic_name text,selling_price numeric(12,2) NOT NULL DEFAULT 0,purchase_cost numeric(12,2) NOT NULL DEFAULT 0,reorder_level integer NOT NULL DEFAULT 0,controlled_drug boolean NOT NULL DEFAULT false,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS batches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid NOT NULL REFERENCES products(id),batch_number text NOT NULL,expiry_date date,quantity_received integer NOT NULL,quantity_available integer NOT NULL,purchase_cost numeric(12,2) NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(product_id,batch_number));
CREATE TABLE IF NOT EXISTS sales(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES users(id),subtotal numeric(12,2) NOT NULL DEFAULT 0,grand_total numeric(12,2) NOT NULL DEFAULT 0,payment_status text NOT NULL DEFAULT 'pending',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sale_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sale_id uuid NOT NULL REFERENCES sales(id),product_id uuid NOT NULL REFERENCES products(id),batch_id uuid NOT NULL REFERENCES batches(id),quantity integer NOT NULL,unit_price numeric(12,2) NOT NULL,total_amount numeric(12,2) NOT NULL);
CREATE TABLE IF NOT EXISTS payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sale_id uuid NOT NULL REFERENCES sales(id),payment_type text NOT NULL,amount numeric(12,2) NOT NULL,status text NOT NULL DEFAULT 'pending',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS stock_movements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid NOT NULL REFERENCES products(id),batch_id uuid REFERENCES batches(id),movement_type text NOT NULL,quantity integer NOT NULL,before_qty integer NOT NULL,after_qty integer NOT NULL,user_id uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS controlled_drug_register(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid NOT NULL REFERENCES products(id),batch_id uuid NOT NULL REFERENCES batches(id),prescription_id text,patient_name text NOT NULL,quantity integer NOT NULL,dispensed_by uuid REFERENCES users(id),approved_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sync_queue(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),entity_type text NOT NULL,entity_id uuid NOT NULL,payload_json jsonb NOT NULL,status text NOT NULL DEFAULT 'pending',attempts integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS batches_product_expiry ON batches(product_id,expiry_date);
